"use client";

import { cn } from "@/lib/utils";
import type { Variants } from "motion/react";
import {
 LazyMotion,
 domMin,
 m,
 useAnimation,
 useReducedMotion,
} from "motion/react";
import {
 forwardRef,
 useCallback,
 useImperativeHandle,
 useRef,
 type HTMLAttributes,
} from "react";
export interface ListChevronsDownUpIconHandle {
 startAnimation: () => void;
 stopAnimation: () => void;
}

interface ListChevronsDownUpIconProps extends Omit<
 HTMLAttributes<HTMLDivElement>,
 | "color"
 | "onDrag"
 | "onDragStart"
 | "onDragEnd"
 | "onAnimationStart"
 | "onAnimationEnd"
 | "onAnimationIteration"
> {
 size?: number;
 duration?: number;
 isAnimated?: boolean;
 color?: string;
}

const ListChevronsDownUpIcon = forwardRef<
 ListChevronsDownUpIconHandle,
 ListChevronsDownUpIconProps
>(
 (
  {
   onMouseEnter,
   onMouseLeave,
   className,
   size = 24,
   duration = 1,
   isAnimated = true,
   color,
   ...props
  },
  ref,
 ) => {
  const controls = useAnimation();
  const reduced = useReducedMotion();
  const isControlled = useRef(false);

  useImperativeHandle(ref, () => {
   isControlled.current = true;
   return {
    startAnimation: () =>
     reduced ? controls.start("normal") : controls.start("animate"),
    stopAnimation: () => controls.start("normal"),
   };
  });

  const handleEnter = useCallback(
   (e?: React.MouseEvent<HTMLDivElement>) => {
    if (!isAnimated || reduced) return;
    if (!isControlled.current) controls.start("animate");
    else onMouseEnter?.(e as any);
   },
   [controls, reduced, isAnimated, onMouseEnter],
  );

  const handleLeave = useCallback(
   (e?: React.MouseEvent<HTMLDivElement>) => {
    if (!isControlled.current) controls.start("normal");
    else onMouseLeave?.(e as any);
   },
   [controls, onMouseLeave],
  );

  const rowVariants: Variants = {
   normal: { scaleX: 1 },
   animate: (i: number) => ({
    scaleX: [1, 0.6, 1],
    transition: {
     duration: 0.5 * duration,
     ease: "easeInOut",
     delay: i * 0.1 * duration,
    },
   }),
  };

  const topVariants: Variants = {
   normal: { y: 0 },
   animate: {
    y: [0, 2, -0.5, 0],
    transition: {
     duration: 0.6 * duration,
     ease: "easeInOut",
     times: [0, 0.35, 0.7, 1],
    },
   },
  };

  const bottomVariants: Variants = {
   normal: { y: 0 },
   animate: {
    y: [0, -2, 0.5, 0],
    transition: {
     duration: 0.6 * duration,
     ease: "easeInOut",
     times: [0, 0.35, 0.7, 1],
    },
   },
  };

  return (
   <LazyMotion features={domMin} strict>
    <m.div
     className={cn("inline-flex items-center justify-center", className)}
     onMouseEnter={handleEnter}
     onMouseLeave={handleLeave}
     {...props}
     style={{ color, ...props.style }}
    >
     <m.svg
      xmlns="http://www.w3.org/2000/svg"
      width={size}
      height={size}
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth="2"
      strokeLinecap="round"
      strokeLinejoin="round"
      animate={controls}
      initial="normal"
     >
      <m.path
       d="M3 5h8"
       variants={rowVariants}
       custom={0}
       style={{ transformBox: "view-box", originX: "3px", originY: "5px" }}
      />
      <m.path
       d="M3 12h8"
       variants={rowVariants}
       custom={1}
       style={{ transformBox: "view-box", originX: "3px", originY: "12px" }}
      />
      <m.path
       d="M3 19h8"
       variants={rowVariants}
       custom={2}
       style={{ transformBox: "view-box", originX: "3px", originY: "19px" }}
      />
      <m.path d="m15 5 3 3 3-3" variants={topVariants} />
      <m.path d="m15 19 3-3 3 3" variants={bottomVariants} />
     </m.svg>
    </m.div>
   </LazyMotion>
  );
 },
);

ListChevronsDownUpIcon.displayName = "ListChevronsDownUpIcon";
export { ListChevronsDownUpIcon };
